// ═══════════════════════════════════════════════════════════════
// SPOTIFY PARSER V5 - Handles direct action strings + natural language
// ═══════════════════════════════════════════════════════════════

const input = $input.first().json;
const rawQuery = (input.query || '').trim();
const request = rawQuery.toLowerCase();

let action = 'search';
let query = rawQuery;

console.log('[Spotify] Raw input:', rawQuery);
console.log('[Spotify] Lowercase:', request);

// ═══════════════════════════════════════════════════════════════
// Step 1: Handle direct action strings (sent by ARYA agent)
// ═══════════════════════════════════════════════════════════════
if (request === 'play_pause' || request === 'pause' || request === 'resume' ||
    request === 'unpause' || request === 'continue' || request === 'stop') {
  action = 'play_pause';
  query = '';
  console.log('[Spotify] → Direct play_pause command');
  return { json: { action, query } };
}

if (request === 'next' || request === 'next_track' || request === 'skip') {
  action = 'next';
  query = '';
  console.log('[Spotify] → Direct next command');
  return { json: { action, query } };
}

if (request === 'previous' || request === 'previous_track' || request === 'prev' || request === 'back') {
  action = 'previous';
  query = '';
  console.log('[Spotify] → Direct previous command');
  return { json: { action, query } };
}

// ═══════════════════════════════════════════════════════════════
// Step 2: Handle natural language phrases
// ═══════════════════════════════════════════════════════════════
if (request.match(/ (pause|unpause|resume|stop|continue) /) &&
    !request.match(/ (play|search|find|put on) /)) {
  action = 'play_pause';
  query = '';
  console.log('[Spotify] → Natural language play_pause');
  return { json: { action, query } };
}

if (request.match(/ (next|skip) /) &&
    !request.match(/ (play|search|find) /)) {
  action = 'next';
  query = '';
  console.log('[Spotify] → Natural language next');
  return { json: { action, query } };
}

if (request.match(/ (previous|back|go back|last song) /) &&
    !request.match(/ (play|search|find) /)) {
  action = 'previous';
  query = '';
  console.log('[Spotify] → Natural language previous');
  return { json: { action, query } };
}

// ═══════════════════════════════════════════════════════════════
// Step 3: Everything else is a search
// ═══════════════════════════════════════════════════════════════
action = 'search';
query = rawQuery
  .replace(/ (play|search|for|on|in|spotify|the|a) /gi, '')
  .replace(/\s+/g, ' ')
  .trim();

if (!query) {
  query = rawQuery;
}

console.log('[Spotify] → Search:', query);

const result = { action, query };
console.log('[Spotify] FINAL:', JSON.stringify(result));
return { json: result };
